import sys


def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    pts = list(set((int(data[1 + 2 * i]), int(data[2 + 2 * i])) for i in range(n)))
    if len(pts) == 1:
        print(1, 0)
        return
    corners = set()
    area2 = 0
    for a in pts:
        for b in pts:
            if a == b:
                continue
            ok = True
            for c in pts:
                cr = (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0])
                if cr < 0:
                    ok = False
                    break
                if cr == 0:
                    if not (min(a[0], b[0]) <= c[0] <= max(a[0], b[0]) and min(a[1], b[1]) <= c[1] <= max(a[1], b[1])):
                        ok = False
                        break
            if ok:
                corners.add(a)
                corners.add(b)
                area2 += a[0] * b[1] - b[0] * a[1]
    print(len(corners), abs(area2))


